import{_ as a,o as e,c as d,ag as o}from"./chunks/framework.CtWPcAmt.js";const p=JSON.parse('{"title":"第 14 章：规则、记忆与个人偏好","description":"全局规则与项目规则、长期偏好与临时上下文、记忆的写入/更新/淘汰、错误规则如何持续放大问题；产出个人 Agent 协作约定。","frontmatter":{"title":"第 14 章：规则、记忆与个人偏好","description":"全局规则与项目规则、长期偏好与临时上下文、记忆的写入/更新/淘汰、错误规则如何持续放大问题；产出个人 Agent 协作约定。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/14-rules-memory.md","filePath":"guide/14-rules-memory.md","lastUpdated":null}'),r={name:"guide/14-rules-memory.md"};function l(i,t,n,s,h,c){return e(),d("div",null,[...t[0]||(t[0]=[o(`<h1 id="第-14-章-规则、记忆与个人偏好" tabindex="-1">第 14 章：规则、记忆与个人偏好 <a class="header-anchor" href="#第-14-章-规则、记忆与个人偏好" aria-label="Permalink to &quot;第 14 章：规则、记忆与个人偏好&quot;">​</a></h1><h2 id="本章解决什么问题" tabindex="-1">本章解决什么问题 <a class="header-anchor" href="#本章解决什么问题" aria-label="Permalink to &quot;本章解决什么问题&quot;">​</a></h2><p>Skill 解决「单类任务怎么做」，本章解决「<strong>跨任务它该永远知道什么</strong>」：你的偏好（用中文回复、格式习惯）、项目的规矩（命名规范、边界）、以及那些「上次说过这次别忘」的事。用不好，它每次像失忆；用过头，一条错误规则会让所有任务持续变糟。产出：<strong>个人 Agent 协作约定</strong>。</p><h2 id="从一个真实场景开始" tabindex="-1">从一个真实场景开始 <a class="header-anchor" href="#从一个真实场景开始" aria-label="Permalink to &quot;从一个真实场景开始&quot;">​</a></h2><p>我在实测中发现一个规律：<strong>规则会放大</strong>。一款产品只要没有规则约束，就越权读取工作区文件；而一款产品只要自检规则写得太松（「认为全部通过」），就会在多个维度上漏报问题（第 5 章 Qoder 页）。<strong>反过来</strong>：正确的规则（「自检必须列出实际读取清单」）能让 Agent 的表现稳定变好。</p><p>规则是杠杆：一条好规则，杠杆放大正确；一条坏规则，杠杆放大错误。所以「给 Agent 定规则」必须像「给组织定制度」一样谨慎。</p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><ol><li><strong>两类规则要分清</strong>：全局规则（所有任务生效：语言、风格、安全底线）与项目规则（该项目生效：命名、口径、边界）；</li><li><strong>记忆分三层</strong>：产品内置记忆（偏好、历史）、项目状态文件（CONTEXT.md，第 11 章）、对话内临时上下文——三层职责不同，别混用；</li><li><strong>记忆要写、要更新、要淘汰</strong>：定期检查「这条规则还对吗？这条记忆还准吗？」过时记忆=污染源；</li><li><strong>错误规则放大问题</strong>：写规则前先想「这条会不会在特殊场景伤害正确性」；</li><li><strong>协作约定要「书面化 + 可检查」</strong>：口头说「你注意点」没用，写成规则文件才生效。</li></ol><h2 id="必要概念" tabindex="-1">必要概念 <a class="header-anchor" href="#必要概念" aria-label="Permalink to &quot;必要概念&quot;">​</a></h2><ul><li><strong>全局规则（Global rules）</strong>：对该产品所有任务生效的规则（通常在设置的「规则/指令」区）。</li><li><strong>项目规则（Project rules）</strong>：仅在特定项目生效的规则（通常在项目目录，如 <code>AGENTS.md</code>、<code>CONTEXT.md</code>）。</li><li><strong>记忆（Memory）</strong>：产品保存的长期信息（偏好、约定、历史要点）。白话解释：Agent 的「长期记忆笔记本」。</li><li><strong>淘汰（Eviction）</strong>：主动删除过时/错误的记忆。白话解释：定期清理笔记本里划掉的旧页。</li><li><strong>放大效应（Amplification）</strong>：规则对 Agent 行为的一致性影响——好规则稳定变好，坏规则稳定变坏。</li></ul><h2 id="个人-agent-协作约定-模板" tabindex="-1">个人 Agent 协作约定（模板） <a class="header-anchor" href="#个人-agent-协作约定-模板" aria-label="Permalink to &quot;个人 Agent 协作约定（模板）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>内容</th><th>存放位置</th></tr></thead><tbody><tr><td>全局安全底线</td><td>不执行删除/覆盖；不自动发送/发布；不联网搜索未知来源；敏感信息用变量</td><td>产品的全局规则区</td></tr><tr><td>全局风格</td><td>默认中文；先结论后细节；表格呈现对比；标注「已验证/推断」</td><td>产品的全局规则区</td></tr><tr><td>项目规则</td><td>命名规范、输出目录、口径、禁区</td><td>项目根 <code>AGENTS.md</code> 或 <code>CONTEXT.md</code></td></tr><tr><td>项目状态</td><td>进度、决策、易变信息核验日期</td><td><code>CONTEXT.md</code>（第 11 章）</td></tr><tr><td>会话临时</td><td>本次任务的背景、材料入口</td><td>任务卡（第 7 章）</td></tr></tbody></table><h2 id="跟着做-建立并维护你的协作约定" tabindex="-1">跟着做：建立并维护你的协作约定 <a class="header-anchor" href="#跟着做-建立并维护你的协作约定" aria-label="Permalink to &quot;跟着做：建立并维护你的协作约定&quot;">​</a></h2><h3 id="第一步-写「全局安全底线」" tabindex="-1">第一步：写「全局安全底线」 <a class="header-anchor" href="#第一步-写「全局安全底线」" aria-label="Permalink to &quot;第一步：写「全局安全底线」&quot;">​</a></h3><p>用命令式写 3–5 条，覆盖第 8 章高风险动作。示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- 未经明确许可，不得删除、覆盖或移动任何现有文件；</span></span>
<span class="line"><span>- 不得执行联网、发送、发布、付款类操作；</span></span>
<span class="line"><span>- 涉及来源、数字、日期时必须标注「已验证」或「推断」；</span></span>
<span class="line"><span>- 输出到任务指定的 output 目录，不修改其他位置。</span></span></code></pre></div><h3 id="第二步-写「项目规则」" tabindex="-1">第二步：写「项目规则」 <a class="header-anchor" href="#第二步-写「项目规则」" aria-label="Permalink to &quot;第二步：写「项目规则」&quot;">​</a></h3><p>为你的长期项目（序章任务所在项目）写 <code>AGENTS.md</code> 或并入 CONTEXT.md：命名规范、输出位置、口径、禁区。</p><h3 id="第三步-检查产品记忆区" tabindex="-1">第三步：检查产品记忆区 <a class="header-anchor" href="#第三步-检查产品记忆区" aria-label="Permalink to &quot;第三步：检查产品记忆区&quot;">​</a></h3><p>找到产品的「记忆/偏好/规则」设置（各产品位置不同，第 5 章界面讲解可参考），确认你写入的规则在正确层级，且没有与项目规则冲突。</p><h3 id="第四步-每两周做一次「记忆清理」" tabindex="-1">第四步：每两周做一次「记忆清理」 <a class="header-anchor" href="#第四步-每两周做一次「记忆清理」" aria-label="Permalink to &quot;第四步：每两周做一次「记忆清理」&quot;">​</a></h3><p>检查：哪条规则已过时？哪条记忆已不准？哪条偏好其实你已改变？<strong>删除/更新，写进协作约定文件的「变更记录」</strong>。</p><h3 id="第五步-验证放大方向" tabindex="-1">第五步：验证放大方向 <a class="header-anchor" href="#第五步-验证放大方向" aria-label="Permalink to &quot;第五步：验证放大方向&quot;">​</a></h3><p>用一个小任务测试：加一条规则前后，同一任务的行为是否按预期方向变好？如果没变好甚至变差，回滚规则。</p><h2 id="一个完整示例" tabindex="-1">一个完整示例 <a class="header-anchor" href="#一个完整示例" aria-label="Permalink to &quot;一个完整示例&quot;">​</a></h2><p>本书项目的协作约定（实际生效中）：</p><ul><li>全局风格规则（写作类）：「先结论后解释；术语首次出现给白话；不堆产品宣传语；区分事实/实测/推断」——这直接来自 <code>docs/03-editorial-guide.md</code>，并落地为章节模板（<code>templates/chapter-template.md</code>）；</li><li>全局安全底线：截图脱敏、价格标注核验日期、Claude 封号只写个案；</li><li>项目规则（<code>docs/</code> 系列）：每份文档只负责一个主题、易变信息集中维护（<code>docs/07</code>）、产品页引用而非复制价格；</li><li>维护机制：内容清单（<code>docs/04-content-backlog.md</code>）就是「记忆清理」的载体——已完成项打勾，过时项标注。</li></ul><p>效果：20 多个章节结构一致、事实口径统一、易变信息集中在 <code>docs/07</code> 一处维护——<strong>规则放大了正确</strong>。</p><h2 id="常见错误与恢复方法" tabindex="-1">常见错误与恢复方法 <a class="header-anchor" href="#常见错误与恢复方法" aria-label="Permalink to &quot;常见错误与恢复方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>加了规则反而更差</td><td>规则与场景冲突</td><td>回滚，加「适用范围」再试</td></tr><tr><td>它总忘你的偏好</td><td>规则放错层级（放对话没放全局）</td><td>移到全局规则区</td></tr><tr><td>记忆里全是过时信息</td><td>从不清理</td><td>两周一次记忆清理</td></tr><tr><td>项目规则与全局规则打架</td><td>层级冲突</td><td>明确「项目规则优先于全局」的说明</td></tr><tr><td>规则越加越多，行为僵化</td><td>过度规则化</td><td>砍到 80% 场景够用，删极端条款</td></tr></tbody></table><h2 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h2><ul><li><strong>规则文件会反复被 Agent 读取</strong>：绝不写入密钥、账号、身份证号；</li><li>全局规则里写死「永远允许/永远禁止」要慎重——用「未经许可禁止 X」而非「禁止 X 一切情况」留出例外空间；</li><li>团队/公司环境：项目规则需符合组织政策，规则里不要夹带个人违规约定。</li></ul><h2 id="本章练习" tabindex="-1">本章练习 <a class="header-anchor" href="#本章练习" aria-label="Permalink to &quot;本章练习&quot;">​</a></h2><p>30 分钟：完成你的「个人 Agent 协作约定」：全局安全底线 3–5 条 + 项目规则 + 产品记忆区检查 + 一次记忆清理。路线 B 读者重点写「风格偏好」，路线 C/D 读者重点写「安全底线与项目规则」。</p><h2 id="你应该带走的成果" tabindex="-1">你应该带走的成果 <a class="header-anchor" href="#你应该带走的成果" aria-label="Permalink to &quot;你应该带走的成果&quot;">​</a></h2><ul><li><strong>个人 Agent 协作约定</strong>（全局安全底线 + 项目规则 + 记忆维护机制）。</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>全局规则管所有任务，项目规则管一个项目；</li><li>记忆分三层：内置记忆、状态文件、临时上下文；</li><li>记忆要写、要更新、要淘汰；</li><li>规则是杠杆，错误规则会放大问题；</li><li>至此第四篇完成：上下文 → 模板 → Skill → 规则记忆，你的「个人工具箱」初具规模。</li></ol>`,38)])])}const g=a(r,[["render",l]]);export{p as __pageData,g as default};
